  'Não associar': 'Non collegare',
  'Alterações aprovadas ou em curso com este equipamento e a janela aberta agora. A escrita fica registada na alteração.': 'Modifiche approvate o in corso che includono questo dispositivo e la cui finestra è aperta ora. La scrittura viene registrata nella modifica.',
